using System;
using System.Collections.Generic;
using System.Linq;
namespace ConstructionEmpire.Data.Presentation
{
    public sealed class HelpTopic {public string Id,Category,Title,Summary,Body,Keywords;}
    public static class HelpCatalog
    {
        public static readonly IReadOnlyList<HelpTopic> Topics=new HelpTopic[]{
new HelpTopic {Id="start",Category="Getting started",Title="Your first company",Summary="Choose an opportunity, estimate the complete scope, win the bid, then organize its work.",Body="1. Start paused and inspect Bidding. Compare client budget, location, deadline and quality.\n2. Review the estimate and set profit and contingency. Submitting resolves the tender immediately; winning is not guaranteed.\n3. Open a won project and choose Start. Order the materials, assign your crew to an eligible internal phase, and request quotes for specialist phases.\n4. Run time at 1x. Check Schedule, Finance and alerts. Repair or refuel equipment and replace missing supplies when work stops.\n5. Complete all phases and inspections. Final payment can arrive later, and retention waits until the warranty period ends.",Keywords="tutorial|begin|getting started|guide"},
new HelpTopic {Id="dashboard",Category="Workspace",Title="Dashboard",Summary="The company overview brings together financial health, active work, warnings and opportunities.",Body="The top metrics show the whole company. Project rows show weighted progress, expected profit, deadline and current risk. Click a project name to inspect it.\nThe financial chart compares magnitudes; it is not a time-series bank statement. Read Finance for ledger details. Green indicates healthy/complete, amber means warning, red means critical, and blue is informational.\nHover any item for context in the help strip; press F1 or choose Read more to open its topic.",Keywords="dashboard|overview|metric|chart|healthy|warning|critical"},
new HelpTopic {Id="time",Category="Getting started",Title="Time and pause",Summary="Speed changes how many fixed simulation hours run; opening menus pauses the company.",Body="Pause is safe for planning. 1x, 2x, 5x, 10x and 25x drain more fixed-hour ticks without changing the economic tick length. The driver limits catch-up after a stall.\nDeadlines, wages, scheduled deliveries, loan payments and market events use game time. Regular shifts only work their permitted hours. Waiting overnight can be correct, rather than a stalled simulation.\nLoaded games start paused. Choose a speed to resume. Help pauses time so you can read without incurring new costs.",Keywords="clock|speed-|1x|2x|5x|10x|25x|pause|day |hour"},
new HelpTopic {Id="saves",Category="Getting started",Title="Save, load and recovery",Summary="Use three manual slots; autosave and Save and quit use their own separate slot.",Body="Game menu offers New, Resume, Continue, Save, Load and backup recovery. Start a new company lets you choose its name, world seed, starting cash and a city in the UK, US, Canada or Australia. Your starting office and jobs are located there. Existing saved worlds keep their original regions. Continue selects the latest saved slot by modification time.\nEach successful replacement keeps the previous file as a backup. Loading validates the file and reconstructs the simulation before replacing the live company. Corruption or an incompatible rules version is rejected.\nAutosave runs periodically after game time advances. Save before quitting or making major decisions. Save and quit writes the separate autosave slot. Files are stored in your Windows user profile, outside the installation directory.\nA long-running company can take longer to restore because its deterministic history is replayed. Never edit save files manually.",Keywords="save|load|recover|backup|continue|quit|new company"},
new HelpTopic {Id="projects",Category="Commercial",Title="Projects and lifecycle",Summary="An opportunity becomes won or lost after bidding; a won contract must be started explicitly.",Body="Available means open to bids. Bidding is the submission transition. Won reserves the contract for you, but construction does not begin until Start. Active means resources and dependencies can advance work. Complete requires every phase and its inspection gate to finish.\nThe Projects browser searches title, client and location, filters status and region, and sorts by deadline, budget, progress or status. Suggested next actions point to relevant screens; use Schedule for the full assignment and dependency details. Compare workload with your existing commitments before starting another site. Crews, equipment and office capacity are shared constraints.\nGenerated opportunities arrive through the market in regions where you operate. Different work profiles change phase quantities, specialist scope, site exposure and deadlines.",Keywords="projects|project detail|active-count|status|available|won|lost|start project"},
new HelpTopic {Id="bidding",Category="Commercial",Title="Bidding and competition",Summary="The tender weighs price and capability; a cheaper bid improves competitiveness but may lose money.",Body="Choose the office region and opportunity. Set desired profit and contingency, review the estimate, then submit the offer. Each opportunity accepts one player submission.\nThe seeded outcome uses price, reputation, experience, quality, relationship, completion time, certifications and market fit. Rival archetypes differ in price, speed, quality and local/specialist strength.\nCompetitor signals are qualitative; exact rival bid prices are intentionally hidden. A narrow loss is still a lost contract. Competitors can also claim unattended opportunities on their cadence.",Keywords="bidding|bid|tender|competitor|quote price|submit"},
new HelpTopic {Id="estimates",Category="Commercial",Title="Estimates and pricing",Summary="Bid price equals estimated cost plus desired profit plus risk contingency.",Body="Labor, materials, equipment, specialist subcontractors and overhead form the cost estimate. Authored specialist phase hours and fixed phase costs feed the playable project estimate. Market rates can move before work starts.\nProfit and contingency are each percentages of base estimated cost, not compounded percentages of each other. Research improves the displayed confidence range; it does not guarantee the actual result.\nReview scope and cash timing before accepting a low-margin job. A client budget is not money already transferred to your bank.",Keywords="estimates|estimate|desired profit|labor cost|overhead|confidence|accuracy"},
new HelpTopic {Id="contingency",Category="Commercial",Title="Risk contingency",Summary="Contingency is a price allowance for uncertainty, not a promise that costs cannot overrun.",Body="A larger allowance can absorb delays, repairs, extra procurement or rework, but makes your bid less competitive. It is added to estimated cost separately from desired profit.\nExample: cost 50,000, profit 12% and contingency 8% produce a bid of 60,000. You still pay actual expenses as they arise.\nUse the risk factors, supply reliability and deadline slack to judge the allowance rather than using the same percentage for every project.",Keywords="risk contingency|risk margin|estimate-contingency"},
new HelpTopic {Id="contract",Category="Commercial",Title="Contracts and payment stages",Summary="A contract defines agreed value, deadline, staged payments, retention and late penalties.",Body="Upfront payment arrives when the signed contract starts. Progress payments become eligible at configured completion thresholds. Final payment follows completion and its configured delay.\nRetention is withheld from the ordinary stages and released after the warranty period. Late completion can incur penalties, subject to the contract cap.\nStarting a contract does not credit its full value immediately. Inspect Project Detail / Finance to see obligations and timing.",Keywords="contract|upfront|final payment|payment schedule|penalty"},
new HelpTopic {Id="changes",Category="Commercial",Title="Change orders",Summary="A scope proposal can alter price, deadline, labor and materials; accept it before that phase starts.",Body="An active project can propose an additional scope package on an unstarted, unbooked internal phase. Review offered price, estimated extra cost and requested time.\nAccept applies the resource and contract amendments together; reject leaves the original scope intact. Negotiation may improve the price, but the client may withdraw the offer.\nThe current model permits one proposal per project. New price is not immediate earned revenue or cash: the extra work and payment milestones still matter.",Keywords="change order|scope|counteroffer|negotiate|proposal"},
new HelpTopic {Id="clients",Category="Commercial",Title="Clients and relationships",Summary="Reliable completion builds trust, and relationship strength contributes to later bid decisions.",Body="The Clients screen lists the client, current relationship and completed-project count. Punctual completion increases trust; delays and poor quality can reduce it.\nReputation belongs to the company, while relationship belongs to a specific client. Generated briefs can return to the same client.\nPreference descriptions provide context; the current release does not implement separate client-specific weighting or negotiated credit terms for every preference.",Keywords="clients|client|relationship|trust"},
new HelpTopic {Id="schedule",Category="Delivery",Title="Schedule and dependencies",Summary="A phase can start only after every prerequisite is complete and its resources are available.",Body="Read planned start/finish, actual dates and current delay in Schedule. Foundation waits for excavation; multiple branches may be eligible in parallel.\nReserve an eligible crew and the required equipment with start/end windows. Travel time may require a later start. Pending reservations activate on simulation ticks.\nA phase may wait for material, fuel, a worker, a subcontractor, an inspection or site conditions. Inspect those blockers rather than simply increasing speed.",Keywords="schedule|phase|prerequisite|dependency|planned|actual start|actual completion"},
new HelpTopic {Id="critical-path",Category="Delivery",Title="Critical path and float",Summary="A critical phase has no spare schedule time; delaying it pushes back the predicted finish.",Body="The scheduler computes the longest dependent chain from the task graph. Float is the time a noncritical task can slip without moving overall completion.\nProgress that falls behind the plan triggers recalculation. A previously noncritical branch can become critical. Prioritize its resources, supply deliveries and inspections.\nThe deadline is a contract promise; the forecast is a prediction. The two dates can differ.",Keywords="critical path|critical-path|float"},
new HelpTopic {Id="bookings",Category="Delivery",Title="Reservations and double-booking",Summary="A crew, worker or machine cannot be committed to overlapping work windows across the company.",Body="Scheduling uses one company-wide registry, including different offices and projects. Copies of a resource with the same identity do not bypass the conflict check.\nCancel an unused reservation before reassigning its resource. A subcontractor award is a separate commitment and cannot be canceled as a crew reservation.\nA booked phase may still wait for its prerequisites or a shared blocker. Inspect the reservation status and actual start.",Keywords="reservation|reserve|booking|assign|release crew|cancel booking|travel"},
new HelpTopic {Id="progress",Category="Delivery",Title="How construction progresses",Summary="Progress multiplies productivity, labor, equipment, materials, site conditions and weather.",Body="The exact chain is Base Productivity \u00d7 Labor Efficiency \u00d7 Equipment Efficiency \u00d7 Material Availability \u00d7 Site Conditions \u00d7 Weather Modifier. Each factor can limit output.\nMissing required material or unavailable required equipment can stop progress. Costs and obligations may still exist while you wait.\nProject progress is the duration-weighted average of its phases, not the count of completed tasks. The final phase must pass applicable inspection gates before completion.",Keywords="progress|completion|productivity|efficiency|site conditions"},
new HelpTopic {Id="workers",Category="Resources",Title="Employees",Summary="Skill, trade, experience, reliability, safety, morale and fatigue affect the workforce.",Body="Employees hold identity, wage, certifications and current project/task assignments. The starter roster contains five workers and a supervisor.\nCompatible skills and supervision improve crew efficiency. Absence reduces available capacity; fatigue raises exposure and reduces effective output.\nRegional hiring recruits a crew from an office workforce pool. The current hiring flow operates on those crews rather than a full individual employment market.",Keywords="employees|employee-count|worker|skill|experience|certification|morale|reliability"},
new HelpTopic {Id="crews",Category="Resources",Title="Crews and working hours",Summary="Named crews share tasks; regular rest trades calendar speed for lower fatigue and cost exposure.",Body="Crew productivity sums worker productivity. Cost per hour sums wages. Efficiency combines compatible skill, experience, supervisor quality, fatigue and research modifiers; equipment and material availability remain separate progress factors.\nNew companies use regular weekday shifts. Crews lets you enable overtime or weekends. Overtime uses the configured wage multiplier for the selected overtime shift.\nWorking longer may accelerate a deadline while increasing wages and fatigue. Do not book the same crew on two sites at once.",Keywords="crews|crew|overtime|weekend|shift|fatigue|supervisor|rest"},
new HelpTopic {Id="equipment",Category="Resources",Title="Equipment and fleet",Summary="Buy or rent the machines required by your phases, then manage fuel, condition and commitments.",Body="Equipment lists condition, status, location, assignment and fuel. A phase requires the configured machine type and simultaneous count.\nBuying reduces liquid cash as a capital purchase; ownership costs accrue as configured. Daily rental includes idle days until return. Release all assignments and open reservations before sale or return.\nBroken equipment must be repaired. Empty fuel must be replenished. Retired or returned machines are removed from the active fleet count.",Keywords="equipment|equipment-count|fleet|excavator|pickup|buy |rent |return|sell"},
new HelpTopic {Id="maintenance",Category="Resources",Title="Condition, repairs and fuel",Summary="Low condition raises breakdown exposure; repair and refueling are separate actions with costs.",Body="Condition falls through use. Breakdowns make a required machine unavailable and can stop its phase. Repair restores condition to the configured repair level rather than creating a new vehicle.\nFuel consumption uses the equipment profile and research savings. Refuel fills the tank and charges the missing amount.\nOwned equipment costs, rental charges, operating costs, fuel and repairs are different entries; inspect the ledger to understand the total.",Keywords="condition|repair|maintenance|fuel|refuel|breakdown"},
new HelpTopic {Id="materials",Category="Resources",Title="Materials and inventory",Summary="On-hand stock is shared inventory; ordered stock does not become usable until delivery.",Body="Material types have units, prices and supply requirements. A phase consumes its required materials as work advances. Without sufficient stock, the material-availability factor limits or stops work.\nCompare on-hand, ordered and remaining requirements. Shared stock can be consumed by another active project, so planning must cover the whole company.\nMaterials includes a remaining-supplies planner. Choose reliability, lowest cost or fastest delivery, review each material and approve the total before purchasing. Shared stock and pending company orders are subtracted; they are not reserved for this project. Price changes, insufficient cash or unfillable materials stop the batch before orders are placed. Individual quantity and shipping controls remain below the plan.",Keywords="materials|material|inventory|stock|on-hand|quantity|storage"},
new HelpTopic {Id="procurement",Category="Resources",Title="Ordering and shipping",Summary="Standard delivery is cheaper; expedited shipping reduces lead time at a premium.",Body="Choose a supplier with available capacity and order the required quantity. A bulk tier can reduce unit price for larger orders. Transport to remote sites adds time and cost.\nThe order becomes a purchase obligation; availability begins only when its scheduled delivery event occurs. A failed reliability roll produces a delay notification and rescheduled arrival.\nResearch can unlock automatic reordering. Turn it on explicitly and review its spending limits; automation uses the same order rules as manual procurement.",Keywords="shipping|expedited|standard|delivery|procurement|bulk|order|lead time"},
new HelpTopic {Id="suppliers",Category="Resources",Title="Suppliers and price changes",Summary="Compare price, reliability, available capacity, lead time and relationship before choosing a supplier.",Body="Each supplier offers specific materials. Prices respond to overall market conditions and individual bounded price drift. Existing orders retain their quoted terms.\nCapacity is reserved by open orders and released on delivery. Successful deliveries develop the relationship. A cheap offer may bring a greater risk of delay.\nSupplier quality is shown as profile information; it is not yet a complete material-to-final-quality simulation.",Keywords="suppliers|supplier|unit price|capacity|volatility"},
new HelpTopic {Id="subcontractors",Category="Resources",Title="Specialist subcontractors",Summary="Specialist phases need a matching awarded subcontractor rather than your internal crew.",Body="Request competing quotes for Electrical, Plumbing, HVAC, Roofing, Landscaping or Structural work. Compare price, duration and the qualitative reliability signal.\nAwarding commits the company and adds the quoted cost. Availability and capacity limit simultaneous work. A reliability failure delays availability and blocks phase work through the same work-provider mechanism used by crews.\nMaterials and required equipment still matter. An award does not bypass prerequisites, site conditions or inspections.",Keywords="subcontractors|subcontractor|specialist|award|request quotes|electrical|plumbing|hvac|roofing|landscaping|structural"},
new HelpTopic {Id="finance",Category="Money",Title="Finance and the ledger",Summary="Read earned profit and liquid cash separately; the ledger explains both.",Body="Revenue is earned work. Expense is an incurred cost. Cash receipts and cash payments are the timing of money entering and leaving the account.\nProject totals attach costs to a specific job; company overhead can exist without a project. Finance also exposes banking, insurance, tax and outstanding obligations.\nA capital purchase or loan changes cash without being ordinary project revenue. Use the ledger category and kind together.",Keywords="finance|ledger|financial|transaction"},
new HelpTopic {Id="cash",Category="Money",Title="Cash and cash flow",Summary="Cash is available money now; a profitable company can still run out before its client pays.",Body="Cash flow follows receipts and payments. Wages, materials, rentals and loan installments may fall due before a progress milestone pays.\nAn overdrawn state is explicitly flagged; it is not silently treated as profitable liquidity. Consider staged work, a smaller commitment, better payment timing or a loan whose repayments you can afford.\nExample: earning 30,000 of work against 20,000 of cost is profitable, but spending that 20,000 before receiving the client payment still consumes cash.",Keywords="cash-flow|cash flow|cash|overdrawn|liquid|bank balance"},
new HelpTopic {Id="profit",Category="Money",Title="Revenue, costs and profit",Summary="Profit equals earned revenue minus accrued expenses; forecasts include work still to come.",Body="Revenue recognition advances with completed work. An invoice or receipt is a separate timing event. Expenses include work, procurement, overhead, rework, maintenance and other incurred costs.\nCurrent profit uses what is earned and incurred so far. Forecast profit estimates the final result, including remaining work and approved noncontract income such as insurance settlement.\nPositive profit is not permission to ignore cash flow. Compare both before expansion.",Keywords="revenue|expenses|profit|current-cost|incurred|forecast cost|earned"},
new HelpTopic {Id="budget",Category="Money",Title="Budgets and overruns",Summary="Budget is a spending target, not a reserved cash account or the signed contract value.",Body="An overrun alert fires when accrued project costs exceed its budget. Forecasts can warn earlier when expected final cost looks too high.\nContract value sets agreed revenue; budget measures planned spending; cash is the company bank position. These are three different numbers.\nChange orders can amend project budget and contract value. Risk, rework and delays can still erode the margin after amendment.",Keywords="budget|overrun|allowance"},
new HelpTopic {Id="retention",Category="Money",Title="Retention and warranty release",Summary="Retention is earned contract money withheld until the warranty release condition is met.",Body="The contract specifies the retention percentage and warranty duration. Ordinary payment stages exclude that retained portion. Completion creates its later receivable, and cash arrives only when release is due.\nDo not count retention as spendable cash when planning the next project. It can explain why completed profitable work has not yet replenished the bank.\nThe current warranty mechanism controls release timing; a full dynamic warranty-claim system is not implemented.",Keywords="retention|warranty"},
new HelpTopic {Id="receivables",Category="Money",Title="Receivables and payables",Summary="Receivables are money owed to you; payables are bills you still owe.",Body="A receivable can already contribute to earned income without being cash. A payable can already reduce profit before cash leaves the account.\nInspect due dates. Insurance claims can be approved as receivables before settlement, and contract payments can wait for their configured delay.\nOverlapping due dates can create a cash deficit even when total receivables exceed payables.",Keywords="receivable|payable|obligation|invoice|due date|payment received"},
new HelpTopic {Id="loans",Category="Money",Title="Banking, debt and interest",Summary="A loan increases cash now but creates principal and interest repayments later.",Body="Choose principal, term, purpose and supported collateral in Finance. The banking system checks its lending constraints and applies the configured/market-linked interest terms.\nLoan drawdown is not project revenue. Repayment of principal and payment of interest have different financial meanings.\nBorrow against expected cash receipts conservatively; a delayed project can make the next installment harder to meet.",Keywords="loan|debt|banking|interest|principal|collateral|credit"},
new HelpTopic {Id="insurance",Category="Money",Title="Insurance and claims",Summary="Coverage trades recurring premiums for partial compensation after eligible losses.",Body="Select General Liability, Equipment, Workers Compensation or Project coverage. Enabling a policy charges its applicable premium; cancellation stops future cover and does not retroactively erase costs.\nCovered incidents can generate a claim after deductible and payout rules. Duplicate claims for the same incident are rejected. Approved claims become receivables and settle after a configured delay.\nUncovered losses remain your expense. Insurance does not restore a broken machine or remove a work stoppage by itself.",Keywords="insurance|premium|coverage|claim|deductible"},
new HelpTopic {Id="tax",Category="Money",Title="Tax and reserves",Summary="Recurring tax assessments use the simulator configuration rather than any real-world tax jurisdiction.",Body="The tax system applies configured rules on its cadence. Cash held today may be needed for a future assessment.\nKeep working capital for payroll, suppliers, debt and tax rather than investing every available pound in new capacity.\nConsult ledger entries for recorded assessments and payments. These simplified mechanics are game rules, not accounting or tax advice.",Keywords="tax|reserve"},
new HelpTopic {Id="risk",Category="Risk and quality",Title="Risk score and exposure",Summary="Risk combines named site, schedule, supply, design, weather and workforce factors.",Body="Low, Medium, High and Critical are weighted score bands. Inspect the underlying causes: difficulty, tight deadline, soil, remoteness, subcontractor reliability, shortages, complexity, weather volatility and crew experience.\nA higher score increases event exposure; it is not a guaranteed incident or a countdown. Seeded probability rolls keep saved simulations reproducible.\nReduce controllable factors with reliable suppliers, realistic commitments, rest, training and maintained equipment.",Keywords="risk score|risk|exposure|difficulty|soil|remoteness|complexity"},
new HelpTopic {Id="weather",Category="Risk and quality",Title="Weather and site conditions",Summary="Regional weather and local site conditions multiply progress rather than changing the formula.",Body="Weather drifts with a seeded random process and seasonal frequency. Indoor phases can have lower exposure than outdoor work.\nAccess constraints, soil, remoteness and difficulty affect the site multiplier. Unexpected ground conditions can trigger investigation, expense and a stoppage.\nLook at the project forecast after conditions change. Extra speed cannot overcome a zero progress modifier.",Keywords="weather|rain|storm|season|ground|site condition|access"},
new HelpTopic {Id="safety",Category="Risk and quality",Title="Safety, absence and fatigue",Summary="Rest, skill, supervision, training and equipment condition help control disruption risk.",Body="Worker absences reduce available crew capacity until their return. Safety incidents can stop work, add investigation costs and reduce reputation.\nFatigue grows while working and recovers during rest. Regular shifts help; overtime can improve near-term output at the cost of wages and exposure.\nTrain an assigned crew through the project risk controls. Repair equipment and review site conditions before simply increasing simulation speed.",Keywords="safety|incident|absence|absent|training|injury"},
new HelpTopic {Id="quality",Category="Risk and quality",Title="Quality and inspections",Summary="Inspection failures require rework and reinspection before a phase can finish.",Body="Quality, compliance and worker or subcontractor skill influence inspection outcomes. Foundation, structure, services and final work have configured checkpoints.\nA failed inspection adds remediation costs, work hours and a stop period. Completion remains blocked until reinspection passes; a visual 100% approach is not permission to skip that gate.\nQuality affects the completed-project reputation assessment. The wider material-quality and warranty-claim model remains limited in this candidate.",Keywords="quality|inspection|compliance|rework|premium quality"},
new HelpTopic {Id="forecast",Category="Risk and quality",Title="Forecasts and proactive alerts",Summary="Forecasts project completion and final cost from current progress, costs and risk.",Body="A forecast is recalculated on relevant events. Changing weather, missing materials, delayed tasks or new costs can move it.\nProactive alerts warn about thresholds such as schedule slippage or low equipment condition before failure becomes critical. They can clear when conditions improve.\nReactive notifications record something that happened. Do not confuse an historical incident with a currently active warning.",Keywords="forecast|expected date|expected completion|proactive|threshold|remaining"},
new HelpTopic {Id="notifications",Category="Workspace",Title="Notifications and navigation",Summary="The notification history records events with severity, time and related entity.",Body="Click a notification to navigate to the relevant project or management screen. Saved games preserve notification history along with tutorial state.\nA notification is historical. A resolved breakdown can remain in the list after the equipment is repaired. Proactive alerts instead track current thresholds.\nBudget, material, equipment, absence, safety, inspection and reputation events can create entries.",Keywords="notifications|notification|activity|alert|event"},
new HelpTopic {Id="company",Category="Growth",Title="Company levels and objectives",Summary="Build a track record to earn levels and pursue company-wide objectives.",Body="Promotions depend on completed projects, earned revenue and reputation together. Research uses the earned company level. Promotions are retained if finances later weaken.\nLong-term goals track completed projects, net asset value, reputation and regional offices. Sandbox play continues after goals are reached.\nValuation includes cash, receivables, payables, debt and the configured value of owned fleet; it is not simply accumulated profit.",Keywords="company|level|promotion|objective|valuation|rename"},
new HelpTopic {Id="reputation",Category="Growth",Title="Reputation",Summary="Reputation reflects results and influences client confidence in future bids.",Body="Project completion adjusts reputation for profitability, punctuality and quality; safety incidents can reduce it. The rating is bounded from 0 to 100.\nA strong reputation helps competitiveness and can satisfy regional or progression gates, but does not guarantee every bid.\nDo not confuse company reputation with a particular client relationship or a supplier reliability score.",Keywords="reputation|track record"},
new HelpTopic {Id="research",Category="Growth",Title="Research and automation",Summary="Upgrades require money, time and prerequisites, then modify existing systems.",Body="Research lists available upgrades, dependencies, cost and effect. A started upgrade completes on the simulation clock and applies its named modifier.\nEstimation accuracy, crew efficiency, procurement discounts, fuel savings and reliability layer into the existing calculations. They do not create separate simulation rules.\nProcurement and scheduling automation require their unlocks and explicit opt-in. Monitor automation status, daily spend limits and resource conflicts; automation cannot supply absent capacity or skip specialist awards.",Keywords="research|upgrade|automation|automated|reorder|unlock"},
new HelpTopic {Id="world",Category="Growth",Title="World map and offices",Summary="Expansion opens regional workforce and opportunity pools with travel and operating costs.",Body="Inspect a region on the map. Its reputation/capital threshold may require either or both conditions. An office establishes local operations; hire its regional crew to use that workforce.\nOffice capacity limits active projects and staffing. Rent or purchase changes the financial commitment. Distance can increase transport, delivery time and overhead.\nNew companies can explore four countries and twelve cities: select a country, then a city to review its costs, unlock requirements and local jobs. Regional cost multipliers affect new offices and local wages; favored work categories receive extra weight in opportunity generation. Established offices source deliveries locally. All markets use a common GBP ledger and fictional economic values. Existing saved companies keep their original world. Generated opportunities respect the region project categories. Opening another office does not make crew or equipment double-booking legal.",Keywords="world map|region|office|expansion|map|hire"},
new HelpTopic {Id="generation",Category="Growth",Title="Generated opportunities and project variety",Summary="The seeded generator creates repeatable briefs with different work profiles and commercial pressures.",Body="The market periodically fills available regional capacity according to demand. You can also request a batch through the office controls. Existing available opportunities count toward the region cap.\nNew-company generation draws from residential, warehouse, hospitality and office profiles. Workloads differ by phase, with combinations of refurbishment, structure, services, finishes and external work. Site difficulty, soil, access, deadline slack, client and scale vary.\nProfiles unlock across company levels. Each generated job retains a valid prerequisite graph and gets its own runtime phase copies. Saves preserve the starting generator settings and replay the same seeded decisions.",Keywords="generated|generation|opportunit|new projects|project type|brief"},
new HelpTopic {Id="settings",Category="Workspace",Title="Settings, keyboard and display",Summary="Use window/fullscreen controls and keyboard focus to make the workspace comfortable.",Body="Settings provides fullscreen and window-size choices. The dashboard preserves its controls and content across layouts; larger windows show more information without scrolling.\nTab moves focus among controls; Enter activates buttons. F1 opens context help. Escape closes Help. The searchable Help library stays available from the top bar and Game menu.\nHelp pauses game time and closes back to your current workspace. Choose a speed when you are ready to resume.",Keywords="settings|fullscreen|resolution|keyboard|help|search"}};
        public static HelpTopic Get(string id)=>Topics.FirstOrDefault(t=>t.Id==id)??Topics[0];
        public static IReadOnlyList<HelpTopic> Search(string query)
        {query=(query??"").Trim();return Topics.Where(t=>query.Length==0 || (t.Title+" "+t.Category+" "+t.Summary+" "+t.Body+" "+t.Keywords).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).ToList();}
        public static HelpTopic Match(string text)
        {text=text??"";return Topics.SelectMany(t=>t.Keywords.Split('|').Select(k=>new {Topic=t,Key=k})).Where(x=>ContainsTerm(text,x.Key)).OrderByDescending(x=>x.Key.Length).Select(x=>x.Topic).FirstOrDefault();}
        private static bool ContainsTerm(string text,string term)
        {
            int start=0;
            while(start<text.Length){int index=text.IndexOf(term,start,StringComparison.OrdinalIgnoreCase);if(index<0)return false;int end=index+term.Length;if((index==0 || !char.IsLetterOrDigit(text[index-1])) && (end==text.Length || !char.IsLetterOrDigit(text[end])))return true;start=index+1;}
            return false;
        }
        public static HelpTopic ForControl(string label,string tooltip,string screen)=>Match(label)??Match(tooltip)??Resolve("",screen);
        public static HelpTopic Resolve(string text,string screen)
        {
            var match=Match(text);if(match!=null)return match;
            switch(screen){case "Dashboard":return Get("dashboard");case "Projects":return Get("projects");case "Project Detail":return Get("projects");case "Bidding":return Get("bidding");case "Estimates":return Get("estimates");case "Schedule":return Get("schedule");case "Employees":return Get("workers");case "Crews":return Get("crews");case "Equipment":return Get("equipment");case "Materials":return Get("materials");case "Suppliers":return Get("suppliers");case "Subcontractors":return Get("subcontractors");case "Clients":return Get("clients");case "Finance":return Get("finance");case "Company":return Get("company");case "Research":return Get("research");case "World Map":return Get("world");case "Notifications":return Get("notifications");case "Settings":return Get("settings");default:return Get("dashboard");}
        }
    }
}
